  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<void> _initFuture;

  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _initFuture = _loadData();
  }

  Future<void> _loadData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    await Future.wait(<Future<void>>[
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
        setState(() {
          _currencies = page.items;
        });
      }),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> value) {
        setState(() {
          _news = value;
        });
      }),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _initFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }

          return ListView(
            padding: const EdgeInsets.all(16),
            children: <Widget>[
              Text(
                loc.currencyRate,
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              if (_currencies.isEmpty)
                const Center(child: Text('No data'))
              else
                ..._currencies.map((CurrencyModel currency) {
                  return Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: _CurrencySummaryCard(currency: currency),
                  );
                }),
              const SizedBox(height: 24),
              Text(
                loc.news,
                style: Theme.of(context).textTheme.headlineSmall,
              ),
              if (_news.isEmpty)
                const Center(child: Text('No data'))
              else
                ..._news.map((NewsModel newsItem) {
                  return Padding(
                    padding: const EdgeInsets.only(bottom: 8),
                    child: _NewsSummaryCard(news: newsItem),
                  );
                }),
            ],
          );
        },
      ),
    );
  }
}

class _CurrencySummaryCard extends StatelessWidget {
  const _CurrencySummaryCard({required this.currency});

  final CurrencyModel currency;

  @override
  Widget build(BuildContext context) {
    return Card(
      child: ListTile(
        title: Text(currency.name),
        subtitle: Text('${currency.code} ${currency.nominalRate}'),
